import React from 'react';
import styled from 'styled-components';
import { FaLinkedin } from 'react-icons/fa';

const Footer = (props) => {
    return (
        <FooterBox>
            <CompanyName>Biuro Rachunkowe AKSIOM</CompanyName>
            <FooterContent>NIP: 6442324607</FooterContent>
            <FooterContent>Regon: 243418808</FooterContent>
            <FaLinkedin size={48} style={{ 'padding': '48px' }} />
            <p style={{ 'textAlign': 'center' }}>© Copyright 2020. All Rights Reserved.</p>
        </FooterBox>
    )
}

export default Footer

const FooterBox = styled.div`
    padding: 48px;
    background-color: #D5992E
    align-content: center;
`;

const Row = styled.div`
    display: flex;
    flex-direction: row;
`;

const CompanyName = styled.div`
    font-size: 1.25rem;
    font-family: 'Nunito', sans-serif;
    font-weight: bold;
    padding-bottom: 20px;
    text-align: center;
`;

const FooterContent = styled.div`
    font-size: 1rem;
    font-family: 'Source Sans Pro', sans-serif;
    text-align: center;
`;
